<!DOCTYPE html>
<html lang="en" data-theme="light">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="description" content="Meet the Patch Patrol, a Paderborn team exploring secure, human-guided software engineering with AI.">
  <title>Team The Patch Patrol | Agentic SE Lab</title>
  <script>
    (() => {
      let theme;
      try {
        theme = localStorage.getItem("upb-theme");
      } catch (_) {}
      if (theme !== "light" && theme !== "dark") {
        theme = window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light";
      }
      document.documentElement.setAttribute("data-theme", theme);
    })();
  </script>
  <style>
    :root {
      --accent: #E4007C;
      --bg: #FFF8E7;
      --text: #1D1D1F;
      --muted: #5A5A5F;
      --card: #FFFFFF;
      --card-border: transparent;
      --shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
      --focus: #E4007C;
    }

    [data-theme="dark"] {
      --bg: #14142B;
      --text: #F4F1DE;
      --muted: #B8B5A7;
      --card: #1F1F3D;
      --card-border: #39395A;
      --shadow: none;
    }

    * {
      box-sizing: border-box;
    }

    html {
      scroll-behavior: smooth;
    }

    body {
      margin: 0;
      background: var(--bg);
      color: var(--text);
      font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
      font-size: 1rem;
      line-height: 1.6;
      transition: background-color 200ms ease, color 200ms ease;
    }

    a {
      color: var(--accent);
      text-underline-offset: 0.25rem;
    }

    a:focus-visible,
    button:focus-visible {
      outline: 0.2rem solid var(--focus);
      outline-offset: 0.25rem;
    }

    .site-header {
      padding: 3rem 2rem;
      border-bottom: 1px solid var(--card-border);
      background: linear-gradient(135deg, var(--bg), color-mix(in srgb, var(--bg) 90%, var(--accent)));
    }

    .header-inner,
    main,
    .footer-inner {
      width: min(100%, 70rem);
      margin-inline: auto;
    }

    .header-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 2rem;
    }

    .header-copy {
      max-width: 48rem;
    }

    h1,
    h2,
    h3,
    p {
      margin-top: 0;
    }

    h1 {
      margin-bottom: 0.5rem;
      font-size: 2.5rem;
      line-height: 1.15;
    }

    h2 {
      margin-bottom: 0.5rem;
      font-size: 1.75rem;
      line-height: 1.25;
    }

    h3 {
      margin-bottom: 0.5rem;
      font-size: 1.25rem;
      line-height: 1.3;
    }

    .tagline {
      margin-bottom: 1rem;
      color: var(--muted);
      font-size: 1.125rem;
    }

    nav {
      display: flex;
      flex-wrap: wrap;
      gap: 1.5rem;
    }

    .theme-toggle {
      flex: 0 0 auto;
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      padding: 0.5rem 1rem;
      border: 1px solid var(--card-border);
      border-radius: 999px;
      background: var(--card);
      color: var(--text);
      box-shadow: var(--shadow);
      font: inherit;
      cursor: pointer;
    }

    main {
      padding: 0 2rem;
    }

    section {
      padding-block: 3rem;
      scroll-margin-top: 1.5rem;
    }

    .section-intro {
      max-width: 65ch;
      margin-bottom: 1.5rem;
      color: var(--muted);
    }

    .team-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(16rem, 1fr));
      gap: 1.5rem;
    }

    .member-card {
      display: flex;
      flex-direction: column;
      align-items: flex-start;
      padding: 1.5rem;
      border: 1px solid var(--card-border);
      border-radius: 1rem;
      background: var(--card);
      box-shadow: var(--shadow);
    }

    .member-card img {
      width: 8rem;
      height: 8rem;
      margin-bottom: 1rem;
      border-radius: 50%;
      object-fit: cover;
    }

    [data-theme="dark"] .member-card img {
      filter: brightness(0.9);
    }

    .study {
      margin-bottom: 1rem;
      color: var(--muted);
      font-weight: 600;
    }

    .member-card p {
      max-width: 70ch;
      margin-bottom: 1rem;
    }

    .member-card .fun-fact {
      color: var(--muted);
    }

    .hot-take {
      margin-top: auto !important;
      margin-bottom: 0 !important;
      padding: 0.5rem 1rem;
      border-radius: 0.5rem;
      background: var(--accent);
      color: #FFFFFF;
      font-size: 0.9rem;
      font-weight: 700;
    }

    .future-panel {
      padding: 2rem;
      border: 1px solid var(--card-border);
      border-radius: 1rem;
      background: var(--card);
      box-shadow: var(--shadow);
    }

    .future-panel p {
      max-width: 70ch;
    }

    .future-panel p:last-child {
      margin-bottom: 0;
    }

    .motto {
      display: inline-block;
      margin-top: 0.5rem;
      color: var(--accent);
      font-weight: 700;
    }

    footer {
      padding: 1.5rem 2rem;
      color: var(--muted);
      text-align: center;
      font-size: 0.8rem;
    }

    @media (max-width: 700px) {
      .site-header {
        padding: 2rem 1rem;
      }

      .header-inner {
        flex-direction: column;
        align-items: flex-start;
        gap: 1.5rem;
      }

      main {
        padding-inline: 1rem;
      }

      .team-grid {
        grid-template-columns: 1fr;
      }

      footer {
        padding-inline: 1rem;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      html {
        scroll-behavior: auto;
      }

      *,
      *::before,
      *::after {
        scroll-behavior: auto !important;
        transition-duration: 0.01ms !important;
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
      }
    }
  </style>
</head>
<body>
  <header class="site-header">
    <div class="header-inner">
      <div class="header-copy">
        <h1>The Patch Patrol</h1>
        <p class="tagline">Five humans, one AI co-pilot, and an absolutely unreasonable number of security checks.</p>
        <nav aria-label="Main navigation">
          <a href="#team">Meet the team</a>
          <a href="#future-of-se">Our AI outlook</a>
        </nav>
      </div>
      <button class="theme-toggle" id="theme-toggle" type="button" aria-label="Switch to night mode">
        <span aria-hidden="true">☾</span>
        <span class="toggle-label">Night mode</span>
      </button>
    </div>
  </header>

  <main>
    <section id="team" aria-labelledby="team-heading">
      <h2 id="team-heading">Meet the Patch Patrol</h2>
      <p class="section-intro">
        We are computer science master's students at the Agentic Software Engineering lab, Paderborn University. Cybersecurity, AI, networks, and an eclectic appreciation for anime, travel, and custom audio bring us together. Our motto: trust the tool, verify the output, and never blame the router until you have checked the router.
      </p>

      <div class="team-grid">
        <article class="member-card">
          <img src="{{image:Jenith_avatar.png}}" alt="Avatar of Jenith">
          <h3>Jenith</h3>
          <p class="study">M.Sc. Computer Science, Paderborn University</p>
          <p>Jenith studies computer science and is interested in cybersecurity, SOC operations, vulnerability assessment, Python, and network systems. A memorable debugging session taught Jenith that one misplaced router rule can turn an ordinary script into a convincing digital traffic jam. Jenith sees AI assistants as useful for code, tests, and documentation, but warns that they may quietly introduce logic flaws or security vulnerabilities. Human review is still essential—especially when the network is already looking suspicious.</p>
          <p class="fun-fact"><em>Fun fact: One misplaced router rule once simulated an entire digital traffic jam.</em></p>
          <p class="hot-take">🔥 AI won't replace human minds; it will give peace of mind to people who know how to use it.</p>
        </article>

        <article class="member-card">
          <img src="{{image:prachi avatar.png}}" alt="Avatar of Prachi">
          <h3>Prachi</h3>
          <p class="study">Master's in Computer Science, Paderborn University</p>
          <p>Prachi studies computer science and enjoys debugging, security operations, and travel. At 23, Prachi is emphatically not 15—a fact apparently worth documenting for the record. Prachi finds AI handy for small jobs such as simple code and tests, but points out that plausible-looking output can still be wrong. In security work, careful people remain necessary to read generated code, catch mistakes, and make sure a convenient shortcut hasn't quietly become an open door.</p>
          <p class="fun-fact"><em>Fun fact: Prachi is 23, not 15 years old!</em></p>
          <p class="hot-take">🔥 AI will not take your job. But someone who can check AI code well might.</p>
        </article>

        <article class="member-card">
          <img src="{{image:pratham_avatar.jpg}}" alt="Avatar of Pratham">
          <h3>Pratham</h3>
          <p class="study">M.Sc. Computer Science, Paderborn University</p>
          <p>Pratham studied computer science at the University of Mumbai and now pursues a master's at Paderborn University. Cybersecurity, AI, and anime compete for attention alongside a hands-on interest in DIY audio. Pratham sees AI as an excellent generator of boilerplate and repetitive code, but one that can miss critical security details. A solid understanding of network protocols and hardware interfaces is still needed to check that generated software is both safe and functional.</p>
          <p class="fun-fact"><em>Fun fact: Pratham builds custom home-theater systems in free time.</em></p>
          <p class="hot-take">🔥 AI will write 90% of our code, and we'll spend 100% of our time patching its security vulnerabilities.</p>
        </article>

        <article class="member-card">
          <img src="{{image:vaibhav_avatar.jpg}}" alt="Avatar of Vaibhav">
          <h3>Vaibhav</h3>
          <p class="study">Master's in Computer Science, Paderborn University</p>
          <p>Vaibhav studies computer science and is interested in artificial intelligence, anime, and philosophy. A huge fan of the Harry Potter movies, Vaibhav is prepared to debate both magical systems and software ones. Vaibhav sees AI as a major change in how software is built, helping developers write code and fix bugs faster. Looking ahead, Vaibhav imagines AI taking an increasingly large role—from an initial idea to working software—while the team keeps an eye on what that means for thoughtful engineering.</p>
          <p class="fun-fact"><em>Fun fact: Vaibhav is a huge fan of the Harry Potter movies.</em></p>
          <p class="hot-take">🔥 AI makes shipping software faster, but it trades deep critical thinking for security bugs.</p>
        </article>

        <article class="member-card">
          <img src="{{image:vatsal_avatar.jpeg}}" alt="Avatar of Vatsal">
          <h3>Vatsal</h3>
          <p class="study">M.Sc. Computer Science, Paderborn University</p>
          <p>Vatsal earned a bachelor's degree in computer engineering from CHARUSAT University and is pursuing a master's in computer science at Paderborn. AI, anime, volleyball, sightseeing, and dramas all make the interest list. Though reserved at first, Vatsal is open with friends. Vatsal sees AI as a way to turn ideas into software faster and expects it to assist across the development process. As these tools become more capable, reliability and security will need to keep pace with the convenience.</p>
          <p class="fun-fact"><em>Fun fact: Vatsal may be reserved, but is open about thoughts with friends.</em></p>
          <p class="hot-take">🔥 AI will make routine tasks easy; trusting its generated code without checking security is the real challenge.</p>
        </article>
      </div>
    </section>

    <section id="future-of-se" aria-labelledby="future-heading">
      <h2 id="future-heading">The Future of Software Engineering</h2>
      <div class="future-panel">
        <p>
          We agree that AI is already a capable co-pilot: it can speed up repetitive work, draft code and tests, and help turn ideas into prototypes. But a confident answer is not the same as a correct one. Generated code can miss context, hide logic errors, and open security holes—so review, testing, and human judgment are part of the job, not optional extras.
        </p>
        <p>
          In the next five to ten years, we expect engineers to spend less time typing every line and more time shaping systems, guiding AI tools, and verifying what they produce. Exactly how much gets automated is up for debate; our strongest shared prediction is that security, reliability, and edge-case thinking will matter even more as generated code scales.
        </p>
        <p>
          In short: let AI do the repetitive bits, keep humans responsible for the consequences, and perhaps give the router one final look.
        </p>
        <span class="motto">Ship the idea. Test the code. Patch the plot twist.</span>
      </div>
    </section>
  </main>

  <footer>
    <div class="footer-inner">
      Built by an agent, supervised by humans. <span id="current-year"></span> The Patch Patrol
    </div>
  </footer>

  <script>
    (() => {
      const root = document.documentElement;
      const toggle = document.getElementById("theme-toggle");
      const icon = toggle.querySelector("[aria-hidden='true']");
      const label = toggle.querySelector(".toggle-label");

      function updateToggle(theme) {
        const isDark = theme === "dark";
        icon.textContent = isDark ? "☀" : "☾";
        label.textContent = isDark ? "Day mode" : "Night mode";
        toggle.setAttribute("aria-label", isDark ? "Switch to day mode" : "Switch to night mode");
      }

      updateToggle(root.getAttribute("data-theme"));
      toggle.addEventListener("click", () => {
        const nextTheme = root.getAttribute("data-theme") === "dark" ? "light" : "dark";
        root.setAttribute("data-theme", nextTheme);
        updateToggle(nextTheme);
        try {
          localStorage.setItem("upb-theme", nextTheme);
        } catch (_) {}
      });

      document.getElementById("current-year").textContent = new Date().getFullYear();
    })();
  </script>
</body>
</html>
